// Build the BOUND Protocol Delivery Roadmap — public/bound-architecture.html
//
// Content comes from scripts/architecture-content.json, generated by
// scripts/gen-architecture-content.py from the source architecture overview PDF.
// This script assigns presentation only.
//
// Shares scripts/base.css with the other platform documents. Charts are inline
// SVG so they stay selectable, theme-aware and printable.

import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { PRINT_CSS, PRINT_BUTTON } from "./print-css.mjs";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const doc = JSON.parse(readFileSync(path.join(root, "scripts/architecture-content.json"), "utf8"));

/* ---------- text ---------- */
const esc = s => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const rich = s => esc(s)
  .replace(/&lt;b&gt;/g, "<b>").replace(/&lt;\/b&gt;/g, "</b>")
  .replace(/&lt;i&gt;/g, "<i>").replace(/&lt;\/i&gt;/g, "</i>");

const LABEL_MAX = 60;
function lead(text) {
  const i = text.indexOf(":");
  if (i < 0 || i > LABEL_MAX) return rich(text);
  return `<b>${rich(text.slice(0, i + 1))}</b>${rich(text.slice(i + 1))}`;
}
const cap = t => `<div class="cap">${esc(t)}</div>`;
const para = b => `<p>${b.boldLabel ? lead(b.text) : rich(b.text)}</p>`;
const list = b => `<ul class="find">${
  b.items.map(i => `<li>${b.boldLabel ? lead(i) : rich(i)}</li>`).join("")}</ul>`;

const table = b => `<div class="tbl-scroll"><table><thead><tr>${
  b.head.map(h => `<th>${esc(h)}</th>`).join("")}</tr></thead><tbody>${
  b.rows.map(r => {
    const isTot = /^(total|total budget)$/i.test(String(r[0]).trim());
    return `<tr${isTot ? ' class="tot"' : ""}>${r.map(c => `<td>${esc(c)}</td>`).join("")}</tr>`;
  }).join("")
}</tbody></table></div>` + (b.cap ? cap(b.cap) : "");

const kpis = b => `<div class="kpis">${
  b.items.map(k => `<div class="kpi"><div class="kn${k.c ? " " + k.c : ""}">${esc(k.n)}</div>` +
    `<div class="kl">${esc(k.l)}</div></div>`).join("")}</div>`;

const note = b => `<div class="note${b.kind ? " " + b.kind : ""}">${
  b.head ? `<span class="nh">${esc(b.head)}</span>` : ""}${rich(b.text)}</div>`;

/* ---------- charts ---------- */
const CAT = ["var(--c1)", "var(--c2)", "var(--c3)", "var(--c4)",
             "var(--c5)", "var(--c6)", "var(--c7)", "var(--c8)"];
const W = 880, PADL = 64, PADR = 26, PADT = 26, PADB = 46;
const niceMax = v => {
  if (v <= 0) return 1;
  const e = Math.pow(10, Math.floor(Math.log10(v)));
  return Math.ceil(v / e * 2) / 2 * e;
};
const shell = (title, inner, h, capText) =>
  `<div class="chart"><div class="ct">${esc(title)}</div>` +
  `<svg viewBox="0 0 ${W} ${h}" role="img" aria-label="${esc(title)}" class="cv">${inner}</svg></div>` +
  (capText ? cap(capText) : "");
const shortUSD = v => (Math.abs(v) >= 1e3 ? (v / 1e3).toFixed(0) + "K" : String(v));

function bar(b) {
  const h = 290, max = niceMax(Math.max(...b.vals));
  const n = b.vals.length, band = (W - PADL - PADR) / n, bw = Math.min(band * 0.42, 110);
  const y0 = h - PADB;
  let s = "";
  for (let i = 0; i <= 4; i++) {
    const y = PADT + (h - PADT - PADB) * (i / 4);
    s += `<line x1="${PADL}" y1="${y.toFixed(1)}" x2="${W - PADR}" y2="${y.toFixed(1)}" class="grid"/>`;
    s += `<text x="${PADL - 9}" y="${(y + 3.5).toFixed(1)}" class="ax ar">${esc(shortUSD(max * (1 - i / 4)))}</text>`;
  }
  b.vals.forEach((v, i) => {
    const x = PADL + band * i + (band - bw) / 2;
    const bh = (v / max) * (h - PADT - PADB);
    s += `<rect x="${x.toFixed(1)}" y="${(y0 - bh).toFixed(1)}" width="${bw.toFixed(1)}" height="${bh.toFixed(1)}" rx="3" fill="${CAT[i % CAT.length]}"/>`;
    s += `<text x="${(x + bw / 2).toFixed(1)}" y="${(y0 - bh - 8).toFixed(1)}" class="vl">${esc(b.labels[i])}</text>`;
    s += `<text x="${(x + bw / 2).toFixed(1)}" y="${(y0 + 20).toFixed(1)}" class="ax ac">${esc(b.cats[i])}</text>`;
  });
  s += `<line x1="${PADL}" y1="${y0}" x2="${W - PADR}" y2="${y0}" class="axis"/>`;
  return shell(b.title, s, h, b.cap);
}

function donut(b) {
  const h = 360, cx = 195, cy = h / 2, R = 112, r = 64;
  let a0 = -Math.PI / 2, s = "";
  b.slices.forEach((sl, i) => {
    const a1 = a0 + (sl.pct / 100) * Math.PI * 2;
    const big = a1 - a0 > Math.PI ? 1 : 0;
    const pt = (rad, a) => [cx + rad * Math.cos(a), cy + rad * Math.sin(a)];
    const [x0, y0] = pt(R, a0), [x1, y1] = pt(R, a1), [x2, y2] = pt(r, a1), [x3, y3] = pt(r, a0);
    s += `<path d="M${x0.toFixed(1)} ${y0.toFixed(1)} A${R} ${R} 0 ${big} 1 ${x1.toFixed(1)} ${y1.toFixed(1)} L${x2.toFixed(1)} ${y2.toFixed(1)} A${r} ${r} 0 ${big} 0 ${x3.toFixed(1)} ${y3.toFixed(1)} Z" fill="${CAT[i % CAT.length]}" stroke="var(--surface)" stroke-width="1.5"/>`;
    a0 = a1;
  });
  b.slices.forEach((sl, i) => {
    const y = 40 + i * 33;
    s += `<rect x="368" y="${y - 9}" width="11" height="11" rx="2.5" fill="${CAT[i % CAT.length]}"/>`;
    s += `<text x="388" y="${y}" class="lg">${esc(sl.lab)}</text>`;
    s += `<text x="${W - PADR}" y="${y}" class="lg ar strong">${esc(sl.val)} · ${sl.pct.toFixed(1)}%</text>`;
  });
  return shell(b.title, s, h, b.cap);
}




/* --- contract graph: fixed grid, straight edges, arrowheads on the call direction ---
   The source diagram overflowed two of its labels; boxes here are sized to the
   grid rather than to the text, and both lines are centred inside them. */
function graph(b) {
  const COLS = 3, ROWS = 3;
  const bw = 216, bh = 68, gapx = 52, gapy = 56;
  const gw = COLS * bw + (COLS - 1) * gapx;
  const x0 = (W - gw) / 2, y0 = 22;
  const h = y0 + ROWS * bh + (ROWS - 1) * gapy + 16;
  const cx = n => x0 + n.col * (bw + gapx) + bw / 2;
  const cy = n => y0 + n.row * (bh + gapy) + bh / 2;
  const byId = Object.fromEntries(b.nodes.map(n => [n.id, n]));
  let s = `<defs><marker id="ah" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0 L10 5 L0 10 z" fill="var(--ink3)"/></marker></defs>`;

  // Edges first so the boxes sit on top of the line ends.
  b.edges.forEach(e => {
    const A = byId[e.a], B = byId[e.b];
    let ax = cx(A), ay = cy(A), bx = cx(B), by = cy(B);
    if (A.row === B.row) {                       // horizontal
      const dir = bx > ax ? 1 : -1;
      ax += dir * bw / 2; bx -= dir * bw / 2;
    } else {                                     // vertical
      const dir = by > ay ? 1 : -1;
      ay += dir * bh / 2; by -= dir * bh / 2;
    }
    const both = e.dir === "both";
    s += `<line x1="${ax.toFixed(1)}" y1="${ay.toFixed(1)}" x2="${bx.toFixed(1)}" y2="${by.toFixed(1)}" ` +
         `stroke="var(--ink3)" stroke-width="1.6" marker-end="url(#ah)"` +
         (both ? ` marker-start="url(#ah)"` : ``) + `/>`;
  });

  b.nodes.forEach((n, i) => {
    const x = cx(n) - bw / 2, y = cy(n) - bh / 2;
    s += `<rect x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${bw}" height="${bh}" rx="9" ` +
         `fill="${CAT[i % CAT.length]}" fill-opacity=".13" stroke="${CAT[i % CAT.length]}" stroke-width="1.5"/>`;
    s += `<text x="${cx(n).toFixed(1)}" y="${(cy(n) - 4).toFixed(1)}" class="gn ac">${esc(n.label)}</text>`;
    s += `<text x="${cx(n).toFixed(1)}" y="${(cy(n) + 14).toFixed(1)}" class="gns ac">${esc(n.sub)}</text>`;
  });
  return shell(b.title, s, h, b.cap);
}

/* --- line --- */
function line(b) {
  const h = 300, y0 = h - PADB;
  const all = b.series.flatMap(s => s.vals);
  const lo = Math.min(...all) * 0.92, hi = Math.max(...all) * 1.04;
  const span = (hi - lo) || 1;
  const sx = i => PADL + (W - PADL - PADR) * (i / (b.xs.length - 1));
  const sy = v => PADT + (h - PADT - PADB) * (1 - (v - lo) / span);
  let s = "";
  for (let i = 0; i <= 4; i++) {
    const y = PADT + (h - PADT - PADB) * (i / 4);
    s += `<line x1="${PADL}" y1="${y.toFixed(1)}" x2="${W - PADR}" y2="${y.toFixed(1)}" class="grid"/>`;
    s += `<text x="${PADL - 9}" y="${(y + 3.5).toFixed(1)}" class="ax ar">${(hi - span * (i / 4)).toFixed(1)}%</text>`;
  }
  b.series.forEach(se => {
    const d = se.vals.map((v, i) => `${i ? "L" : "M"}${sx(i).toFixed(1)} ${sy(v).toFixed(1)}`).join(" ");
    s += `<path d="${d}" fill="none" stroke="${CAT[0]}" stroke-width="2.4" stroke-linejoin="round" stroke-linecap="round"/>`;
  });
  b.xs.forEach((x, i) => {
    if (i % 6 !== 5 && i !== 0) return;
    s += `<text x="${sx(i).toFixed(1)}" y="${(y0 + 20).toFixed(1)}" class="ax ac">M${x}</text>`;
  });
  s += `<line x1="${PADL}" y1="${y0}" x2="${W - PADR}" y2="${y0}" class="axis"/>`;
  return shell(b.title, s, h, b.cap);
}

/* --- swimlane: stages across, audiences down --- */
function swimlane(b) {
  const nS = b.stages.length, nL = b.lanes.length;
  const LW = 150, rowH = 92, headH = 62;
  const h = headH + nL * rowH + 12;
  const colW = (W - LW - 16) / nS;
  let s = "";
  b.stages.forEach((st, i) => {
    const x = LW + colW * i;
    s += `<rect x="${(x + 4).toFixed(1)}" y="18" width="${(colW - 8).toFixed(1)}" height="30" rx="6" fill="${CAT[i]}" opacity=".85"/>`;
    s += `<text x="${(x + colW / 2).toFixed(1)}" y="38" class="pb">${esc(st.name)}</text>`;
    s += `<text x="${(x + colW / 2).toFixed(1)}" y="${(headH - 2).toFixed(1)}" class="ax ac">Months ${st.from}\u2013${st.to}</text>`;
  });
  b.lanes.forEach((ln, r) => {
    const y = headH + r * rowH;
    if (r % 2 === 0) s += `<rect x="0" y="${y}" width="${W}" height="${rowH}" fill="var(--ink)" opacity=".03"/>`;
    s += `<text x="6" y="${(y + rowH / 2 + 4).toFixed(1)}" class="lnm">${esc(ln.name)}</text>`;
    ln.cells.forEach((c, i) => {
      const x = LW + colW * i;
      s += `<rect x="${(x + 4).toFixed(1)}" y="${(y + 8).toFixed(1)}" width="${(colW - 8).toFixed(1)}" height="${(rowH - 16).toFixed(1)}" rx="7" fill="${CAT[i]}" opacity=".10" stroke="${CAT[i]}" stroke-opacity=".35"/>`;
      // wrap the cell text to the column width
      const words = c.split(" ");
      const maxc = Math.floor((colW - 26) / 5.6);
      const lines = [];
      let cur = "";
      words.forEach(w => {
        if ((cur + " " + w).trim().length > maxc) { lines.push(cur.trim()); cur = w; }
        else cur += " " + w;
      });
      if (cur.trim()) lines.push(cur.trim());
      lines.slice(0, 4).forEach((ln2, li) => {
        s += `<text x="${(x + colW / 2).toFixed(1)}" y="${(y + 26 + li * 14).toFixed(1)}" class="swc ac">${esc(ln2)}</text>`;
      });
    });
  });
  return shell(b.title, s, h, b.cap);
}


/* ---------- render ---------- */
function render(blocks) {
  return blocks.map(b => {
    switch (b.t) {
      case "p": return para(b);
      case "ul": return list(b);
      case "table": return table(b);
      case "kpis": return kpis(b);
      case "note": return note(b);
      case "bar": return bar(b);
      case "donut": return donut(b);
      case "line": return line(b);
      case "graph": return graph(b);
      case "swimlane": return swimlane(b);
      case "sub": return `<h4 class="sub">${esc(b.title)}</h4>${render(b.blocks)}`;
      default: throw new Error(`unknown block type: ${b.t}`);
    }
  }).join("\n");
}

const B = doc.chapters.map(ch => `<section id="${ch.id}"><div class="sec-head">${
  ch.num ? `<div class="sec-num">${ch.num}</div>` : `<div class="sec-num">§</div>`
}<h2>${esc(ch.title)}</h2></div>
${render(ch.blocks)}
</section>`).join("\n");

const sidebarNav = doc.chapters.map(ch =>
  `<a data-id="${ch.id}" href="#${ch.id}"><span class="snav-num">${ch.num || "§"}</span>${esc(ch.nav)}</a>`
).join("");

